document.outline_text:
[
  {
    "intent": "Introduce why long-running test validation requires lifecycle ownership to transfer to test-genie rather than staying tied to an ephemeral client process.",
    "summary": "Establish the builder context where suites outlast interactive sessions, explaining how test-genie takes ownership of scenario test runs immediately after the invocation command returns so validation identity persists.",
    "target_words": 260
  },
  {
    "intent": "Explain the operational workflow where an operator initiates the suite, retains the run identifier, and completes validation through a unified wait step.",
    "summary": "Detail the concrete execution path where operators start the scenario suite, record the generated run identifier, and wait once on the server-owned execution without remaining tethered to an open terminal.",
    "target_words": 310
  },
  {
    "intent": "Differentiate transport-level disconnections from actual test failures to protect the integrity of failure diagnosis.",
    "summary": "Demonstrate why a cancelled client is not the same thing as an aborted run, ensuring the system preserves uncorrupted logs and prevents network or session interruptions from being misclassified as product defects.",
    "target_words": 290
  },
  {
    "intent": "Conclude on how server-owned validation records establish durable handoffs and governed verification across agents.",
    "summary": "Synthesize how durable server-owned runs turn waiting into a governed capability, preserving an addressable evidence trail that subsequent operators can inspect to make grounded release decisions.",
    "target_words": 260
  }
]

